float sdArc(in SDFG_VEC p, in float radiusA, in float radiusB, in float angle)
{
    vec2  sc = vec2(sin(angle),cos(angle));

    p.x = abs(p.x);
    return ((sc.y*p.x>sc.x*p.z) ? length(p.xz - sc*radiusA) : 
                                  abs(length(p.xz)-radiusA)) - radiusB;
}
